import { Ref, ReactNode } from 'react';

export type TextProps = {
  as?: 'p' | 'span' | 'div';
  children: ReactNode;
  ref?: Ref<HTMLElement>;
};

export function Text({ as = 'p', children, ref }: TextProps) {
  const Tag = as;
  return <Tag ref={ref as Ref<HTMLElement>}>{children}</Tag>;
}
